let p = ctx.player;
if (!p) return;

let inv = p.getInventory();
let foundSlot = -1;

for (let i = 0; i < inv.getContainerSize(); i++) {
    let stack = inv.getItem(i);
    if (!stack.isEmpty() && String(stack.id) === 'minecraft:spider_eye') {
        foundSlot = i;
        break;
    }
}

let dur = Math.round(ctx['vision_duration'] || 300);

if (foundSlot !== -1) {
    inv.getItem(foundSlot).shrink(1);
    if (p.containerMenu) p.containerMenu.broadcastChanges();

    p.potionEffects.add('minecraft:night_vision', dur, 0);
    global.Stones.playSound(p, 'minecraft:entity.spider.ambient', 'players', 1.0, 1.2);
    global.Stones.spawnParticles(p, 'minecraft:end_rod', p.eyePosition, 12, 0.3, 0.3, 0.3, 0.02);
} else {
    p.potionEffects.add('minecraft:blindness', dur, 0);
    global.Stones.playSound(p, 'minecraft:block.sculk_sensor.clicking', 'players', 1.2, 0.5);
    global.Stones.spawnParticles(p, 'minecraft:squid_ink', p.eyePosition, 12, 0.3, 0.3, 0.3, 0.05);
}

global.Stones.setCooldown(p, 'milestone_nighthunter', ctx['hunter_cooldown'] || 200);

let p = ctx.player;
let target = ctx.target || (ctx.event ? ctx.event.target : null);
if (!p || !target) return;
    let bonus = ctx['glow_damage_bonus'] || 4.0;

    if (ctx.event) {
        if (typeof ctx.event.setAmount === 'function') {
            ctx.event.setAmount(ctx.event.getAmount() + bonus);
        } else if (typeof ctx.event.amount !== 'undefined') {
            ctx.event.amount += bonus;
        }
    }

    global.Stones.playSound(p, 'minecraft:entity.experience_orb.pickup', 'players', 0.9, 1.8);
    global.Stones.playSound(p, 'minecraft:entity.arrow.hit_player', 'players', 1.0, 0.5);
    global.Stones.spawnParticles(p, 'minecraft:damage_indicator', target.position().add(0, 1.2, 0), 10, 0.3, 0.3, 0.3, 0.1);
    global.Stones.spawnParticles(p, 'minecraft:crit', target.position().add(0, 1.0, 0), 12, 0.3, 0.3, 0.3, 0.2);
